166	// REV 7.6 V9.6 — minimaler XML-Reader fuer messreihe-Tags (defined/full Mode)
167	struct MessreihenSpec {
168	    std::string              id;
169	    std::string              mode; // "defined" oder "full"
170	    std::vector<std::string> sota_profiles;
171	};
172	
173	[[nodiscard]] std::vector<MessreihenSpec> load_messreihen(std::filesystem::path const& xml_path) {
174	    std::vector<MessreihenSpec> result;
175	    if (!std::filesystem::exists(xml_path)) return result;
176	
177	    std::ifstream      in{xml_path};
178	    std::ostringstream ss;
179	    ss << in.rdbuf();
180	    auto content = ss.str();
181	
182	    std::regex reihe_re{"<messreihe\\s+id\\s*=\\s*\"([^\"]+)\"[^>]*>([\\s\\S]*?)</messreihe>"};
183	    auto       it  = std::sregex_iterator(content.begin(), content.end(), reihe_re);
184	    auto       end = std::sregex_iterator();
185	    for (; it != end; ++it) {
186	        MessreihenSpec spec;
187	        spec.id           = (*it)[1].str();
188	        std::string inner = (*it)[2].str();
189	
190	        std::regex  mode_re{"<mode>(\\w+)</mode>"};
191	        std::smatch mm;
192	        if (std::regex_search(inner, mm, mode_re))
193	            spec.mode = mm[1].str();
194	        else
195	            spec.mode = "defined";
196	
197	        std::regex prof_re{"<profile>([^<]+)</profile>"};
198	        auto       pit  = std::sregex_iterator(inner.begin(), inner.end(), prof_re);
199	        auto       pend = std::sregex_iterator();
200	        for (; pit != pend; ++pit) { spec.sota_profiles.push_back((*pit)[1].str()); }
201	        result.push_back(std::move(spec));
202	    }
203	    return result;
204	}
