519	        cb::WorkloadOptions  w = default_workload_for(kind);
520	
521	        int rc = driver.run_pipeline_full(w);
522	        if (rc != cb::status_ok) {
523	            std::cerr << "Messreihe " << messreihe_name(kind) << " FAILED (status=" << rc << ")\n";
524	            overall_rc = rc;
525	            continue;
526	        }
527	        std::cout << "Messreihe " << messreihe_name(kind) << " OK -> " << (reihe_output / "measurements.csv").string()
528	                  << "\n\n";
529	    }
