22	namespace comdare::messung_driver {
23	
24	// Ein geparstes Achsen-Schlüssel/Wert-Paar (z.B. {"simd","avx2"}).
25	struct AxisKV {
26	    std::string key;
27	    std::string value;
28	};
29	
30	namespace detail {
31	[[nodiscard]] inline std::string trim(std::string_view s) {
32	    std::size_t const a = s.find_first_not_of(" \t");
33	    if (a == std::string_view::npos) return std::string{};
34	    std::size_t const b = s.find_last_not_of(" \t");
35	    return std::string{s.substr(a, b - a + 1)};
36	}
37	} // namespace detail
38	
39	// Parst den codegen-`axes`-String in geordnete Achsen-Paare.
40	// "simd=avx2,layout=soa,alloc=std (real=mimalloc)"
41	//   → [{simd,avx2}, {layout,soa}, {alloc,"std (real=mimalloc)"}]
42	// Tokens ohne '=' werden als positionale Werte (leerer Key) aufgenommen.
43	[[nodiscard]] inline std::vector<AxisKV> parse_axes(std::string_view axes) {
44	    std::vector<AxisKV> out;
45	    std::size_t         pos = 0;
46	    while (pos <= axes.size()) {
47	        std::size_t const      comma = axes.find(',', pos);
48	        std::string_view const tok =
49	            axes.substr(pos, comma == std::string_view::npos ? std::string_view::npos : comma - pos);
50	        std::string const t = detail::trim(tok);
51	        if (!t.empty()) {
52	            std::size_t const eq = t.find('=');
53	            if (eq != std::string::npos) {
54	                out.push_back({detail::trim(std::string_view{t}.substr(0, eq)),
55	                               detail::trim(std::string_view{t}.substr(eq + 1))});
56	            } else {
57	                out.push_back({std::string{}, t});
58	            }
59	        }
60	        if (comma == std::string_view::npos) break;
61	        pos = comma + 1;
62	    }
63	    return out;
64	}
65	
66	// Wert einer benannten Achse (falls vorhanden).
67	[[nodiscard]] inline std::optional<std::string> axis_value(std::vector<AxisKV> const& axes, std::string_view key) {
68	    for (auto const& kv : axes) {
69	        if (kv.key == key) return kv.value;
70	    }
71	    return std::nullopt;
72	}
73	
74	// Generisches Achsen-Item (entkoppelt von LoadedPlugin → testbar).
75	struct AxisItem {
76	    std::string         id;
77	    std::vector<AxisKV> axes;
78	};
79	
80	[[nodiscard]] inline AxisItem make_axis_item(std::string_view id, std::string_view axes_string) {
81	    return AxisItem{std::string{id}, parse_axes(axes_string)};
82	}
83	
84	// Geordnete, eindeutige Achsen-Schlüssel über alle Items (Erst-Vorkommen-Reihenfolge).
85	[[nodiscard]] inline std::vector<std::string> collect_axis_keys(std::vector<AxisItem> const& items) {
86	    std::vector<std::string> keys;
87	    for (auto const& it : items) {
88	        for (auto const& kv : it.axes) {
89	            if (!kv.key.empty() && std::find(keys.begin(), keys.end(), kv.key) == keys.end()) {
90	                keys.push_back(kv.key);
91	            }
92	        }
93	    }
94	    return keys;
95	}
96	
97	// Hierarchischer Achsen-Baum.
98	struct AxisTreeNode {
99	    std::string               axis_key;   // gruppierende Achse dieser Ebene ("" = Wurzel)
100	    std::string               axis_value; // Wert dieser Ebene ("" = Wurzel)
101	    std::vector<AxisTreeNode> children;
102	    std::vector<std::size_t>  item_indices; // nur an Blättern (depth == axis_order.size()) gefüllt
103	};
104	
105	namespace detail {
106	inline void build_subtree(AxisTreeNode& node, std::vector<AxisItem> const& items,
107	                          std::vector<std::size_t> const& subset, std::vector<std::string> const& axis_order,
108	                          std::size_t depth) {
109	    if (depth >= axis_order.size()) {
110	        node.item_indices = subset;
111	        return;
112	    }
113	    std::string const& key = axis_order[depth];
114	    // std::map ⇒ deterministische, wertsortierte Gruppen-Reihenfolge.
115	    std::map<std::string, std::vector<std::size_t>> groups;
116	    for (auto idx : subset) { groups[axis_value(items[idx].axes, key).value_or("<none>")].push_back(idx); }
117	    for (auto const& [val, sub] : groups) {
118	        AxisTreeNode child;
119	        child.axis_key   = key;
120	        child.axis_value = val;
121	        build_subtree(child, items, sub, axis_order, depth + 1);
122	        node.children.push_back(std::move(child));
123	    }
124	}
125	} // namespace detail
126	
127	// Baut den Achsen-Baum, der die Items entlang axis_order hierarchisch gruppiert.
128	[[nodiscard]] inline AxisTreeNode build_axis_tree(std::vector<AxisItem> const&    items,
129	                                                  std::vector<std::string> const& axis_order) {
130	    AxisTreeNode             root;
131	    std::vector<std::size_t> all(items.size());
132	    for (std::size_t i = 0; i < items.size(); ++i) all[i] = i;
133	    detail::build_subtree(root, items, all, axis_order, 0);
134	    return root;
135	}
136	
137	// Anzahl Blatt-Items im (Teil-)Baum.
138	[[nodiscard]] inline std::size_t count_leaf_items(AxisTreeNode const& node) {
139	    if (node.children.empty()) return node.item_indices.size();
140	    std::size_t n = 0;
141	    for (auto const& c : node.children) n += count_leaf_items(c);
142	    return n;
143	}
144	
145	// Item 4 — Achsen-Subtree-Gruppen: Items, die in ALLEN Achsen AUSSER `varying_axis` übereinstimmen.
146	// Innerhalb jeder zurückgegebenen Gruppe variiert NUR `varying_axis` → das ist der saubere
147	// „gleiche SIMD+Layout, vergleiche Allokator-Varianten"-Vergleich. Nur Gruppen mit ≥2 Items.
148	[[nodiscard]] inline std::vector<std::vector<std::size_t>>
149	subtree_groups_varying(std::vector<AxisItem> const& items, std::vector<std::string> const& axis_keys,
150	                       std::string_view varying_axis) {
151	    std::map<std::string, std::vector<std::size_t>> buckets;
152	    for (std::size_t i = 0; i < items.size(); ++i) {
153	        std::string fixed;
154	        for (auto const& k : axis_keys) {
155	            if (k == varying_axis) continue;
156	            fixed += k + '=' + axis_value(items[i].axes, k).value_or("<none>") + ';';
157	        }
158	        buckets[fixed].push_back(i);
159	    }
160	    std::vector<std::vector<std::size_t>> out;
161	    for (auto& [_, v] : buckets) {
162	        if (v.size() >= 2) out.push_back(std::move(v));
163	    }
164	    return out;
165	}
166	
167	} // namespace comdare::messung_driver
