28	    std::regex                    open_tag{"<" + tag_name + "\\s+id\\s*=\\s*\"([^\"]+)\"\\s*>"};
29	    std::regex                    inner_tag{"<(\\w+)>([^<]+)</\\w+>"};
30	    auto                          it  = std::sregex_iterator(content.begin(), content.end(), open_tag);
